"""Maintainers only: rebuild report-template.html = shared CSS + agent footer (from the Off-plan base) + body.html,
then the optional modules (distressed deal, mortgage). build.py uses report-template.html as it is."""
import pathlib, re
here = pathlib.Path(__file__).parent
VERSION = "1.1.0"
_b = here / "../../Off-plan Reports/template/base-template.html"   # Calculators layout; in the skill repo: ../../../offplan-report/kit/template/
src = (_b if _b.exists() else here / "../../../offplan-report/kit/template/base-template.html").read_text().split("\n")   # the off-plan template without its modules
end = src.index("</style>") + 1
css = re.sub(r"Off-plan Report v[0-9.]+", "Ready Property Report v" + VERSION, "\n".join(src[:end]))
fs = next(i for i, l in enumerate(src) if l.startswith("/* brand icons"))
foot = "\n".join(src[fs:fs + 7])
foot = (foot.replace('I am interested to invest in "+D.project', 'I am interested in this unit in "+D.project')
        .replace("WhatsApp me about this project", "WhatsApp me about this unit")
        .replace("(DXB Interact, Bayut, DLD, GenieMap, Google Maps) and the developer's sales offer.", "(DXB Interact, Bayut, DLD, Google Maps) and the listing.")
        .replace("Confirm fees and the payment plan with the developer and DLD before buying.", "Confirm the service charge, fees and any mortgage terms with DLD and your bank before buying."))
foot = re.sub(r"Off-plan Report v[0-9.]+ ©", "Ready Property Report v" + VERSION.rsplit(".", 1)[0] + " ©", foot)
assert "Ready Property Report v1.1 ©" in foot and "the listing." in foot and "your bank" in foot
body = (here / "body.html").read_text()
assert "/*@@FOOTER@@*/" in body
out = css + "\n" + body.replace("/*@@FOOTER@@*/", foot)

# ===== modules (were the separate Distressed and Mortgage reports): switched on by the data =====
#   distressed:true      -> section 1 A: Distressed Deal objectives (7% rental ROI, 10% below what similar units sell for)
#   mortgageReport:true  -> section 1: mortgage deal test (positive cashflow) + section "Your mortgage, year by year"
s=out
def sub(a,b,n=1):
    global s
    assert s.count(a)==n,(a[:80],s.count(a))
    s=s.replace(a,b)
sub('<p>Prepared ${D.date} · ${AGENT.formulas||""}</p>','<p>Prepared ${D.date} · ${AGENT.formulas?AGENT.formulas.replace("Ready Property Evaluation Form",([D.distressed&&"Distressed Deal",D.mortgageReport&&"Mortgage"].filter(Boolean).join(" + ")||"Ready")+" Property Evaluation Form"):""}</p>')
sub('+"Ready property evaluation";','+(D.distressed?"Distressed deal evaluation":D.mortgageReport?"Mortgage property evaluation":"Ready property evaluation");')
sub('<a href="#outcomes">What could happen</a>','<a href="#outcomes">What could happen</a><a href="#mort">Mortgage</a>')
sub('  <section id="market">','  <section id="mort">\n    <h2>3 · Your mortgage, year by year <small id="mt-sub"></small></h2>\n    <p class="sd-take" id="mt-take"></p>\n    <div id="mt-body">\n    <div class="selrow noprint"><span class="seg-lab">Rate</span><div class="seg" id="sel-es" role="group" aria-label="EIBOR scenario"></div></div>\n    <p class="small noprint" id="mt-es-note" style="margin:-4px 0 12px"></p>\n    <div class="card"><div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between"><div class="src-tag" id="mt-ctitle" style="margin:0"></div><div class="seg noprint" id="sel-cu" role="group" aria-label="Show per month or per year"></div></div><div id="mt-chart"></div></div>\n    <div class="tbl-wrap"><table class="mt-tbl" id="mt-tbl"></table></div>\n    <p class="small" id="mt-note"></p>\n    <details class="card mt-det"><summary>Month-by-month schedule</summary><div class="tbl-wrap"><table class="mt-tbl" id="mt-months"></table></div><p class="small" style="margin:8px 0 0">Net yield for each month = that month\'s net cashflow ÷ your cash. Figures are rounded to 2 decimals, so adding up 12 months can differ from the year table by a few hundredths.</p></details>\n    </div>\n  </section>\n\n  <section id="market">')
sub('<h2>1 · Is it a good deal? <small>four quick checks</small></h2>','<h2>1 · Is it a good deal? <small id="deal-sub">four quick checks</small></h2>\n    <h3 class="s2-sub" id="dA" hidden>A · Distressed deal test <small>both objectives must be met</small></h3>\n    <div class="checks objectives" id="objectives" hidden></div>\n    <h3 class="s2-sub" id="dM" hidden>A · Mortgage deal test <small>does the rent cover the mortgage?</small></h3>\n    <div class="checks objectives one" id="mobjectives" hidden></div>\n    <h3 class="s2-sub" id="dB" hidden>B · Market checks <small>price, rent and resale</small></h3>')
sub('.checks{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}',".checks{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.checks.objectives{grid-template-columns:repeat(2,minmax(0,1fr));margin-bottom:16px}.check .fig .sg.pos{color:var(--good)}.check .fig .sg.neg{color:var(--bad)}.check.ok .fig .sg{color:inherit}.s2-sub small{font:500 11px var(--f-display);color:var(--muted);letter-spacing:.08em;text-transform:uppercase;margin-left:8px}@media (max-width:560px){.checks.objectives{grid-template-columns:minmax(0,1fr)}}.checks.objectives.one{grid-template-columns:minmax(0,1fr)}.s2-sub small{font:500 11px var(--f-display);color:var(--muted);letter-spacing:.08em;text-transform:uppercase;margin-left:8px}@media (max-width:980px){.checks.objectives.one{grid-template-columns:minmax(0,1fr)}}.mt-tbl th,.mt-tbl td{padding:7px 10px;text-align:right;white-space:nowrap;font-size:13px;border-bottom:1px solid var(--line)}.mt-tbl th:first-child,.mt-tbl td:first-child{text-align:left}.mt-tbl thead th{font:600 12px var(--f-display);color:var(--muted);position:sticky;top:0;background:var(--surface)}.mt-tbl td.pos{color:var(--good);font-weight:600}.mt-tbl td.neg{color:var(--bad);font-weight:600}.mt-tbl tr.fx td:first-child::after{content:' · fixed';color:var(--muted);font-size:11px}.mt-det summary{cursor:pointer;font:600 14px var(--f-display)}.mt-det .tbl-wrap{max-height:460px;overflow:auto;margin-top:10px}#mt-chart svg{width:100%;height:auto;display:block}.mt-hbox{position:relative}.mt-nav{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:10px 0 2px;padding:6px;border:1px solid var(--line);border-radius:999px;background:var(--surface)}.mt-nav span{font:500 12px var(--f-body);color:var(--muted);text-align:center}.mt-nav span b{color:var(--ink)}.mt-navb{border:0;border-radius:999px;padding:6px 14px;background:var(--accent);color:#0b1a0f;font:700 12px var(--f-display);cursor:pointer;white-space:nowrap}.mt-navb:disabled{background:var(--surface-2);color:var(--muted);cursor:default}#mort .card{margin-bottom:14px}#mort .tbl-wrap{margin-bottom:8px}")
sub("/* ruler */",'/* objectives (form rows C51, C59): Yes / Almost achieved / No */\nif(D.distressed){const ob=(v,y,a)=>v>=y?"good":v>=a?"ok":"bad", ow=c=>c==="good"?"Yes":c==="ok"?"Almost achieved":"No";\nconst o1=ob(r.yld,.07,.06), o2=ob(r.cgr,.1,.07);\n$("#objectives").innerHTML=[\n [o1,"Objective of 7% Rental ROI achieved?",`${ow(o1)} · ${pct(r.yld)}`,`Net rent <b>${aed(r.net)}</b> a year ÷ your cash <b>${aed(r.equity)}</b>${r.ltv?" (after the mortgage payments)":""}. Yes at 7% or more, almost achieved at 6–7%.${r.yld<.07?` The price would need to be <b>${aed(solve(x=>x.yld,.07))}</b> or less for 7%.`:""}`],\n [o2,"Objective of 10% capital appreciation achieved?",`${ow(o2)} · <span class="sg ${r.cgr>=0?"pos":"neg"}">${sgn(r.cgr)}</span>`,`Similar units sold for <b>${fmt(r.comp)}</b> AED/sqft (${r.src.name}); you pay <b>${fmt(r.unitPsf)}</b>. ${r.cgr>=0?`That is ${pct(r.cgr)} of upside to market value`:`You pay ${pct(-r.cgr)} more per sqft than the market`}. Yes at 10% or more, almost achieved at 7–10%.${r.cgr<.1?` The price would need to be <b>${aed(r.comp*D.size/1.1)}</b> or less for 10%.`:""}`]\n].map(([c,q,f,a])=>`<div class="check ${c}"><div class="chead"><div class="ic">${c==="good"?"✓":c==="ok"?"~":"✕"}</div><div class="q">${q}</div></div><div class="fig">${f}</div><div class="a">${a}</div></div>`).join("");}\n/* mortgage deal test: positive cashflow in year 1 (+ how many years of the loan are positive) */\nif(D.mortgageReport){const ob=(v,y,a)=>v>=y?"good":v>=a?"ok":"bad", ow=c=>c==="good"?"Yes":c==="ok"?"Almost achieved":"No";\nconst NY=r.loan?Math.ceil(r.sch.length/12):0, posN=r.loan?Array.from({length:NY},(_,i)=>r.rent-r.sc-r.yrOf(i+1).cost).filter(x=>x>=0).length:0;\nconst o1=r.net>=0?"good":"bad";\n$("#mobjectives").innerHTML=[\n [o1,"Positive cashflow achieved?",`${r.net>=0?"Yes":"No"} · ${r.net>=0?"+":"−"}${aed(Math.abs(r.cf))} a month`,r.loan?`Year 1: rent <b>${aed(r.rent)}</b> − service charge <b>${aed(r.sc)}</b> − mortgage &amp; insurance <b>${aed(r.mYear)}</b> = <b>${aed(r.net)}</b> a year. Positive in <b>${posN} of ${NY}</b> years of the loan (see section 3).`:`Cash purchase: no mortgage, so the rent is all yours. Tap <b>Mortgage: Yes</b> above.`]\n].map(([c,q,f,a])=>`<div class="check ${c}"><div class="chead"><div class="ic">${c==="good"?"✓":c==="ok"?"~":"✕"}</div><div class="q">${q}</div></div><div class="fig">${f}</div><div class="a">${a}</div></div>`).join("");}\n/* mortgage, year by year */\nif(D.mortgageReport){const q=calc({es:ES,ru:rgOf(RI)});\n const esR=v=>clampR(D.eibor.rates[TEN]+v+(+MARG||0)).toFixed(2);$("#mt-es-note").innerHTML=`Rate after the fixed period = ${TEN} EIBOR (${D.eibor.rates[TEN].toFixed(2)}% on ${D.eibor.date}) ± 1% + ${(+MARG||0).toFixed(2)}% bank margin.`;\n $("#sel-es").innerHTML=[[1,`Conservative · ${esR(1)}%`],[0,`Normal ★ · ${esR(0)}%`],[-1,`Optimistic · ${esR(-1)}%`]].map(([v,t])=>`<button aria-pressed="${ES===v}" data-es="${v}">${t}</button>`).join("");\n if(!q.loan){$("#mt-sub").textContent="cash purchase";$("#mt-take").innerHTML="Cash purchase: no mortgage. Tap <b>Mortgage: Yes</b> above to see the loan, the payments and the cashflow for every year.";$("#mt-body").hidden=true;}\n else{$("#mt-body").hidden=false;\n const N=Math.ceil(q.sch.length/12), R=[];for(let i=1;i<=N;i++){const y=q.yrOf(i),net=q.rent-q.sc-y.cost;R.push({...y,net})}\n const pos=R.filter(x=>x.net>=0).length, neg1=R.find(x=>x.net<0), tInt=R.reduce((a,x)=>a+x.it,0), tIns=R.reduce((a,x)=>a+x.lf+x.prop,0), fyY=q.fy&&q.fy<N?q.fy:0;\n const vr=clampR(D.eibor.rates[TEN]+ES+(+MARG||0)), RSm={"1M":1,"3M":3,"6M":6,"1Y":12}[TEN]||3, rsTxt=RSm===1?"every month":RSm===12?"once a year":`every ${RSm} months`, pAfter=(q.sch[Math.min(q.sch.length-1,fyY*12)]||{}).pay||q.emi2;\n $("#mt-sub").textContent=`${aed(q.loan)} loan · ${N} years · ${ES>0?"conservative: EIBOR +1%":ES<0?"optimistic: EIBOR −1%":"normal: EIBOR as today"}`;\n $("#mt-take").innerHTML=(R[0].net>=0?`Year 1 is cash-positive: <b>+${aed(R[0].net/12)}</b> a month after the loan, insurance and service charge.`:`Year 1 is cash-negative: you add <b>${aed(-R[0].net/12)}</b> a month on top of the rent.`)\n   +(fyY?` After the ${fyY}-year fixed period the rate follows ${TEN} EIBOR + ${(+MARG).toFixed(2)}% and resets <b>${rsTxt}</b>${ES?`; in this scenario EIBOR is 1% ${ES>0?"higher":"lower"} than today for the whole variable period, so the rate is <b>${vr.toFixed(2)}%</b>`:` (<b>${vr.toFixed(2)}%</b> today)`} and the payment moves to about <b>${aed(pAfter)}</b> a month.`:"")\n   +` Positive in <b>${pos} of ${N}</b> years${neg1&&R[0].net>=0?` (first negative year: year ${neg1.i})`:""}. Total interest <b>${aed(tInt)}</b>, insurance <b>${aed(tIns)}</b>.`;\n /* chart: what you keep (or add) — one bar per month or one bar per year */\n const MO=q.sch.map(x=>{const pm=(x.m-1)%12===0?q.propY:0,net=q.rent/12-q.sc/12-x.pay-x.lf-pm;return {...x,pm,net}});\n {const isY=CU==="y",S=isY?R.map(x=>({v:x.net,tip:`Year ${x.i}: ${x.net>=0?"+":"−"}${aed(Math.abs(x.net))}`,lab:x.i})):MO.map(x=>({v:x.net,tip:`Month ${x.m} (year ${Math.ceil(x.m/12)}): ${x.net>=0?"+":"−"}${aed(Math.abs(x.net))}`,lab:x.m}));\n  const n=S.length,MW=30,W=isY?1000:Math.max(1000,24+n*MW),H=300,L=12,Rp=12,T=34,B=58,cw=(W-L-Rp)/n,vals=S.map(x=>x.v),hi0=Math.max(0,...vals),lo0=Math.min(0,...vals),sp0=(hi0-lo0)||1,hi=hi0+sp0*.08,lo=lo0<0?lo0-sp0*.14:0,span=hi-lo,ph=H-T-B,y=v=>T+(hi-v)/span*ph,z=y(0),per=isY?1:12;\n  let g="";\n  const band=(a,b,t,c,t2)=>{if(b<=a)return;const bw=(b-a)*cw-4;if(t.length*6.6>bw)t=t2;g+=`<rect x="${L+a*cw}" y="${H-B+18}" width="${bw}" height="22" rx="6" fill="${c}"/><text x="${isY?L+a*cw+bw/2:L+a*cw+10}" y="${H-B+33}" text-anchor="${isY?"middle":"start"}" font-size="12" font-weight="600" fill="var(--ink)">${t}</text>`};\n  const fxAll=q.fy>=N, fe=(fxAll?N:fyY)*per;\n  band(0,fe,`Fixed ${(+RATE).toFixed(2)}% · years 1–${fe/per}`,"color-mix(in srgb,var(--accent) 22%,transparent)",fe*cw>70?`Fixed ${(+RATE).toFixed(2)}%`:"Fixed");\n  if(!fxAll)band(fe,n,`Variable ${R[N-1].rt.toFixed(2)}% (${TEN} EIBOR + ${(+MARG).toFixed(2)}%) · years ${fyY+1}–${N}`,"color-mix(in srgb,var(--muted) 22%,transparent)",`Variable ${R[N-1].rt.toFixed(2)}%`);\n  g+=`<line x1="${L}" x2="${W-Rp}" y1="${z}" y2="${z}" stroke="var(--muted)" stroke-width="1.5"/>`;\n  const fmtv=v=>(v>=0?"+":"−")+fmt(Math.abs(v));\n  S.forEach((x,j)=>{const top=y(Math.max(x.v,0)),bh=Math.max(isY?2:1,Math.abs(y(x.v)-z)),xx=L+j*cw+cw*.14,w=cw*.72;\n   g+=`<rect x="${xx}" y="${top}" width="${w}" height="${bh}" rx="${isY?3:0}" fill="${x.v>=0?"var(--good)":"var(--bad)"}"><title>${x.tip}</title></rect>`;\n   {g+=`<text x="${xx+w/2}" y="${x.v>=0?top-5:z+bh+13}" text-anchor="middle" font-size="${isY?(n>20?10:12):9}" font-weight="600" fill="${x.v>=0?"var(--good)":"var(--bad)"}">${fmtv(x.v)}</text><text x="${xx+w/2}" y="${H-B+12}" text-anchor="middle" font-size="11" fill="var(--muted)">${x.lab}</text>`}});\n  g+=`<text x="${L}" y="16" font-size="12" fill="var(--muted)">${isY?"Each bar = one year of the loan · number = AED left that year":"Each bar = one month of the loan (month number below)"}</text>`;\n  if(!isY)setTimeout(()=>{const w=$("#mt-hs"),a=$("#mt-prev"),b=$("#mt-next"),rg=$("#mt-range");if(!w||!rg)return;const pxPer=w.scrollWidth/n,upd=()=>{const first=Math.max(1,Math.floor(w.scrollLeft/pxPer)+1),last=Math.min(n,Math.floor((w.scrollLeft+w.clientWidth)/pxPer));rg.innerHTML=`Months <b>${first}–${last}</b> of ${n} · scroll sideways or use the arrows`;a.disabled=w.scrollLeft<=2;b.disabled=w.scrollLeft+w.clientWidth>=w.scrollWidth-2};w.onscroll=upd;a.onclick=()=>w.scrollBy({left:-(w.clientWidth-90),behavior:"smooth"});b.onclick=()=>w.scrollBy({left:w.clientWidth-90,behavior:"smooth"});upd()},0);\n  $("#mt-ctitle").textContent=isY?"What is left for you each year":"What is left for you each month";\n  $("#sel-cu").innerHTML=[["m","Per month"],["y","Per year"]].map(([v,t])=>`<button aria-pressed="${(CU||"m")===v}" data-cu="${v}">${t}</button>`).join("");\n  const ms=[[0,q.loan],...[fyY,10,15,20].filter((v,k,a)=>v>0&&v<N&&a.indexOf(v)===k).map(v=>[v,R[v-1].bal]),[N,0]];\n  $("#mt-chart").innerHTML=`<div class="mt-hbox"><div id="mt-hs" style="overflow-x:auto"><svg viewBox="0 0 ${W} ${H}" style="${isY?"":`width:${W}px;max-width:none`}" role="img" aria-label="What you keep or add, ${isY?"per year":"per month"}, for the whole loan">${g}</svg></div></div>${isY?"":`<div class="mt-nav noprint"><button type="button" class="mt-navb" id="mt-prev">‹ Earlier</button><span id="mt-range"></span><button type="button" class="mt-navb" id="mt-next">Later ›</button></div>`}\n  <p class="small" style="margin:8px 0 0"><b style="color:var(--good)">Green</b> bar = the rent pays the mortgage, insurance and service charge and this much is left for you ${isY?"that year":"that month"}. <b style="color:var(--bad)">Red</b> bar = you add this much from your own pocket. The grey line is zero.${isY?"":" Property insurance is paid once a year (month 1 of each year), so that month is a little lower."}</p>\n  <p class="small" style="margin:6px 0 0"><b>Loan left:</b> ${ms.map(([v,b])=>`${v?"after year "+v:"start"} <b>${aed(b)}</b>`).join(" → ")}</p>`;}\n $("#mt-tbl").innerHTML=`<thead><tr><th>Year</th><th>Rate</th><th>Payments</th><th>Interest</th><th>Principal</th><th>Life ins.</th><th>Property ins.</th><th>Loan left</th><th>Net cashflow</th><th>Yield</th><th>Positive?</th></tr></thead><tbody>${R.map(x=>`<tr class="${x.i<=fyY?"fx":""}"><td>${x.i}</td><td>${x.rt.toFixed(2)}%</td><td>${fmt(x.pay)}</td><td>${fmt(x.it)}</td><td>${fmt(x.pr)}</td><td>${fmt(x.lf)}</td><td>${fmt(x.prop)}</td><td>${fmt(x.bal)}</td><td class="${x.net>=0?"pos":"neg"}">${x.net>=0?"+":"−"}${fmt(Math.abs(x.net))}</td><td>${pct(x.net/q.equity)}</td><td class="${x.net>=0?"pos":"neg"}">${x.net>=0?"Yes":"No"}</td></tr>`).join("")}</tbody>`;\n $("#mt-note").innerHTML=`Rent (${aed(q.rent)}) and service charge (${aed(q.sc)}) are kept at today\'s level every year, like your Mortgage form. Insurance: life ${D.mortgage.lifePct}% a month of the loan left, property ${D.mortgage.propPct}% of the price a year (placeholders; ask your bank). Variable rate = ${TEN} EIBOR + bank margin, kept between the floor (${(FLR??D.varDefaults.floor).toFixed(2)}%) and ceiling (${(CEIL??D.varDefaults.ceiling).toFixed(2)}%). Yield = net cashflow ÷ your cash (${aed(q.equity)}).`;\n $("#mt-months").innerHTML=`<thead><tr><th>Month</th><th>Rate</th><th>Payment</th><th>Interest</th><th>Principal</th><th>Life ins.</th><th>Property ins.</th><th>Loan left</th><th>Net cashflow</th><th>Yield</th><th>Positive?</th></tr></thead><tbody>${MO.map(x=>`<tr><td>${x.m}</td><td>${x.rt.toFixed(2)}%</td><td>${fmt(x.pay,2)}</td><td>${fmt(x.it,2)}</td><td>${fmt(x.pr,2)}</td><td>${fmt(x.lf,2)}</td><td>${x.pm?fmt(x.pm,2):"–"}</td><td>${fmt(x.bal,2)}</td><td class="${x.net>=0?"pos":"neg"}">${x.net>=0?"+":"−"}${fmt(Math.abs(x.net),2)}</td><td>${pct(x.net/q.equity)}</td><td class="${x.net>=0?"pos":"neg"}">${x.net>=0?"Yes":"No"}</td></tr>`).join("")}</tbody>`;}}\n/* ruler */')
