sub('{let N=0;document.querySelectorAll("section > h2").forEach(h=>{const sec=h.parentElement,','/* modules switched on by the data: distressed:true (Distressed Deal objectives), mortgageReport:true (mortgage deal test + "Your mortgage, year by year") */\n(function applyMode(){const DIS=!!D.distressed,MR=!!D.mortgageReport,on=(x,v)=>{const e=$(x);if(e&&v)e.hidden=false};\n on("#dA",DIS);on("#objectives",DIS);on("#dM",MR);on("#mobjectives",MR);on("#dB",DIS||MR);\n let k=0;["#dA","#dM","#dB"].forEach(x=>{const e=$(x);if(e&&!e.hidden&&e.firstChild)e.firstChild.textContent=String.fromCharCode(65+k++)+e.firstChild.textContent.slice(1)});\n $("#deal-sub").textContent=DIS&&MR?"distressed + mortgage deal tests + market checks":DIS?"distressed deal test + market checks":MR?"mortgage deal test + market checks":"four quick checks";\n if(!MR){$("#mort").hidden=true;const a=document.querySelector(\'.toc a[href="#mort"]\');if(a)a.hidden=true}})();\n'+'{let N=0;document.querySelectorAll("section > h2").forEach(h=>{const sec=h.parentElement,')
